Future<void> main() async {
  WidgetsFlutterBinding.ensureInitialized();

  await FractalUp.init((options) {
    options.ingestionKey = const String.fromEnvironment('FRACTALUP_INGESTION_KEY');
    options.endpoint = Uri.parse(const String.fromEnvironment('FRACTALUP_ENDPOINT'));
    options.serviceName = 'my-flutter-app';
  }, appRunner: () => runApp(const MyApp()));
}
